t.table(Styles.black6, b -> {
    StringBuilder str = new StringBuilder();
    b.defaults().left();
    b.label(() -> {
        if (!showHint())
            return str;
        str.setLength(0);
        if (!isBuilding && !Core.settings.getBool("buildautopause") && !player.unit().isBuilding()) {
            str.append(Core.bundle.format("enablebuilding", Binding.pauseBuilding.value.key.toString()));
        } else if (player.unit().isBuilding()) {
            str.append(Core.bundle.format(isBuilding ? "pausebuilding" : "resumebuilding", Binding.pauseBuilding.value.key.toString())).append("\n").append(Core.bundle.format("cancelbuilding", Binding.clearBuilding.value.key.toString())).append("\n").append(Core.bundle.format("selectschematic", Binding.schematicSelect.value.key.toString()));
        }
        if (!player.dead() && !player.unit().spawnedByCore()) {
            str.append(str.length() != 0 ? "\n" : "").append(Core.bundle.format("respawn", Binding.respawn.value.key.toString()));
        }
        return str;
    }).style(Styles.outlineLabel);
}).margin

